from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[2];O=R/'renders/references_calques_v1';m=json.loads((O/'manifest.json').read_text());data={}
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
for mode,s in m['scenes'].items():data[mode]={'layers':{n:uri(O/mode/n) for n in s['layers']},'frames':[uri(p) for p in sorted((O/mode/'reflet').glob('*.png'))]}
html='''<!doctype html><meta charset="utf-8"><title>Références · calques séparés</title><style>body{background:#101827;color:#e5eaf5;font:16px system-ui;margin:30px auto;max-width:1150px}h1{font-size:26px}button,select{padding:10px;background:#293b56;color:white;border:1px solid #64738b;border-radius:6px}main{display:flex;gap:20px}canvas{width:100%;image-rendering:pixelated;background:#222}section{flex:1;min-width:0}aside{width:195px}label{display:block;margin:14px 0}p{color:#b6c5d9}small{display:block;margin-top:20px}</style><h1>Trois références · véritables calques PNG</h1><p>Nouvelles générations à valider — ciels, nuages, astres et terrain indépendants. Reflet reconstruit, 64 phases / 5,12 s. Aucun ajout de mer ou de lune à la guilde.</p><select id="mode"><option value="coucher">Côte · coucher de soleil</option><option value="nuit" selected>Côte · nuit</option><option value="guilde">Plateau · guilde</option></select> <button id="pause">Pause</button> <button id="download">Télécharger la composition PNG</button><p id="phase"></p><main><section><canvas width="960" height="600" id="view"></canvas></section><aside id="layers"></aside></main><small>Falaises générées guidées par Métano, non natives. Conversion nocturne : filtre Abyss existant. Clic sur ↓ pour exporter chaque calque ; les PNG sont tous alignés en 960 × 600.</small><script>const DATA=__DATA__;let active,images={},frames=[],running=true,tick=0;const c=document.getElementById('view'),ctx=c.getContext('2d');function img(src){const i=new Image();i.src=src;return i}function save(src,name){const a=document.createElement('a');a.href=src;a.download=name;a.click()}function choose(){active=DATA[document.getElementById('mode').value];images=Object.fromEntries(Object.entries(active.layers).map(([n,s])=>[n,img(s)]));frames=active.frames.map(img);document.getElementById('layers').innerHTML='';for(const [n,s] of Object.entries(active.layers)){const l=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.dataset.name=n;l.append(ch,document.createTextNode(n.replace('.png','')+' '));const a=document.createElement('a');a.href=s;a.download=n;a.textContent='↓';a.style.color='#aee4ff';l.append(a);document.getElementById('layers').append(l)}tick=0}document.getElementById('mode').onchange=choose;document.getElementById('pause').onclick=e=>{running=!running;e.target.textContent=running?'Pause':'Reprendre'};document.getElementById('download').onclick=()=>save(c.toDataURL(),'composition.png');choose();setInterval(()=>{if(running)tick=(tick+1)%64;ctx.clearRect(0,0,960,600);for(const ch of document.querySelectorAll('input[data-name]'))if(ch.checked){let i=ch.dataset.name==='06_reflet.png'?frames[tick]:images[ch.dataset.name];if(i&&i.complete&&i.naturalWidth)ctx.drawImage(i,0,0)}document.getElementById('phase').textContent=frames.length?'Reflet · phase '+String(tick+1).padStart(2,'0')+'/64':'Guilde · fond forestier sans mer';},80);</script>'''
(R/'apercu_references_calques_v1.html').write_text(html.replace('__DATA__',json.dumps(data)),encoding='utf8')
